#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

struct Item {
    int c, w;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<Item> items(n);
    vector<int> dp(n, 1001); // Changed to a 1D vector
    vector<int> sumw(n);

    sumw[0] = 0;
    for(int i = 0; i < n; i++) {
        cin >> items[i].c >> items[i].w;
        sumw[i] = (i > 0) ? sumw[i - 1] + items[i].w : items[i].w;
    }

    // Initialize base cases for dp
    for(int i = 0; i < n - 1; i++)
        if (items[i].c >= items[i + 1].w || items[i + 1].c >= items[i].w) dp[i] = 1;

    for (int k = 2; k < n; k++) {
        vector<int> new_dp(n, 1001); // Temporary vector for the current row
        for (int i = 0; i + k < n; i++) {
            if ((dp[i + 1] == 1 && items[i].c >= sumw[i + k] - sumw[i]) || 
                (dp[i + k - 1] == 1 && items[i + k].c >= sumw[i + k - 1] - (i ? sumw[i - 1] : 0)))
                new_dp[i] = 1;
            else 
                new_dp[i] = min(dp[i + 1], dp[i]) + 1;
        }
        dp.swap(new_dp); // Swap to update the dp vector
    }
    cout << dp[0] << endl;
    return 0;
}

